import express from "express";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { isValidHttpUrl, siteFromUrl, normalizeUrlForCompare } from "../public/js/shared.mjs";
import { readPageDetails } from "./metadata.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = join(__dirname, "..", "public");

const VALID_STATUS = new Set(["to-read", "finished"]);

function newId() {
  return (
    Date.now().toString(36) + Math.random().toString(36).slice(2, 8)
  );
}

function sanitizeTags(tags) {
  if (!Array.isArray(tags)) return undefined;
  const out = [];
  for (const t of tags) {
    if (typeof t !== "string") continue;
    const v = t.trim();
    if (v && !out.includes(v)) out.push(v);
  }
  return out;
}

export function createApp({ store, fetchImpl } = {}) {
  const app = express();
  app.use(express.json());
  app.use(express.static(PUBLIC_DIR));

  app.get("/api/bookmarks", (req, res) => {
    res.json(store.all());
  });

  app.post("/api/bookmarks", async (req, res) => {
    const url = normalizeUrlForCompare(req.body && req.body.url);
    if (!isValidHttpUrl(url)) {
      return res
        .status(400)
        .json({ error: "invalid_url", message: "That doesn't look like a web address." });
    }
    const existing = store.findByUrl(url);
    if (existing) {
      return res
        .status(409)
        .json({ error: "duplicate", message: "You've already saved this link.", bookmark: existing });
    }
    const details = await readPageDetails(url, { fetchImpl });
    const bookmark = {
      id: newId(),
      url,
      title: details.title,
      site: details.site,
      description: details.description || "",
      tags: [],
      note: "",
      status: "to-read", // new links start as "to read" (SCN-004)
      archived: false,
      unreadable: !!details.unreadable, // (SCN-007)
      savedAt: new Date().toISOString(),
    };
    await store.add(bookmark);
    res.status(201).json(bookmark);
  });

  app.patch("/api/bookmarks/:id", async (req, res) => {
    const bm = store.findById(req.params.id);
    if (!bm) return res.status(404).json({ error: "not_found" });

    const body = req.body || {};
    const patch = {};

    if (body.url !== undefined) {
      const url = normalizeUrlForCompare(body.url);
      if (!isValidHttpUrl(url)) {
        return res
          .status(400)
          .json({ error: "invalid_url", message: "That doesn't look like a web address." });
      }
      const clash = store.findByUrl(url);
      if (clash && clash.id !== bm.id) {
        return res
          .status(409)
          .json({ error: "duplicate", message: "Another bookmark already uses this link.", bookmark: clash });
      }
      patch.url = url;
      patch.site = siteFromUrl(url);
      patch.unreadable = false; // the client has taken the address in hand
    }
    if (typeof body.title === "string") patch.title = body.title.trim() || bm.title;
    if (typeof body.description === "string") patch.description = body.description.trim();
    if (typeof body.note === "string") patch.note = body.note.trim();

    const tags = sanitizeTags(body.tags);
    if (tags !== undefined) patch.tags = tags;

    if (body.status !== undefined) {
      if (!VALID_STATUS.has(body.status))
        return res.status(400).json({ error: "invalid_status" });
      patch.status = body.status;
    }
    if (body.archived !== undefined) patch.archived = !!body.archived;

    const updated = await store.update(bm.id, patch);
    res.json(updated);
  });

  app.delete("/api/bookmarks/:id", async (req, res) => {
    const ok = await store.remove(req.params.id); // permanent (SCN-009)
    if (!ok) return res.status(404).json({ error: "not_found" });
    res.status(204).end();
  });

  return app;
}
// Persistent store for bookmarks — a JSON file with atomic writes.
// The collection is personal and single-user, and must survive restarts (NF-1).

import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DEFAULT_FILE = join(__dirname, "..", "data", "bookmarks.json");

export class BookmarkStore {
  constructor(file = DEFAULT_FILE) {
    this.file = file;
    this.bookmarks = [];
    this._writeChain = Promise.resolve();
  }

  async load() {
    await mkdir(dirname(this.file), { recursive: true });
    if (!existsSync(this.file)) {
      this.bookmarks = [];
      return;
    }
    try {
      const raw = await readFile(this.file, "utf8");
      const parsed = JSON.parse(raw);
      this.bookmarks = Array.isArray(parsed) ? parsed : [];
    } catch {
      this.bookmarks = [];
    }
  }

  // Serialise writes and write atomically (temp file + rename).
  _persist() {
    this._writeChain = this._writeChain.then(async () => {
      const tmp = this.file + ".tmp";
      await writeFile(tmp, JSON.stringify(this.bookmarks, null, 2), "utf8");
      await rename(tmp, this.file);
    });
    return this._writeChain;
  }

  all() {
    return this.bookmarks;
  }

  findById(id) {
    return this.bookmarks.find((b) => b.id === id) || null;
  }

  findByUrl(url) {
    const target = (url || "").trim();
    return this.bookmarks.find((b) => b.url === target) || null;
  }

  async add(bookmark) {
    this.bookmarks.unshift(bookmark); // newest first (SCN-001)
    await this._persist();
    return bookmark;
  }

  async update(id, patch) {
    const bm = this.findById(id);
    if (!bm) return null;
    Object.assign(bm, patch);
    await this._persist();
    return bm;
  }

  async remove(id) {
    const i = this.bookmarks.findIndex((b) => b.id === id);
    if (i === -1) return false;
    this.bookmarks.splice(i, 1);
    await this._persist();
    return true;
  }
}
// Reads a page's useful details (title, description, site) by fetching it.
// On any failure — network error, non-HTML, missing fields — it degrades
// gracefully and reports `unreadable: true` with a URL-derived fallback title,
// so a link is never lost. (SCN-001, SCN-007)

import { siteFromUrl, fallbackTitleFromUrl } from "../public/js/shared.mjs";

function decodeEntities(s) {
  if (!s) return s;
  return s
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n));
}

function extractTitle(html) {
  const og = html.match(
    /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i
  );
  if (og) return decodeEntities(og[1].trim());
  const t = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (t) return decodeEntities(t[1].replace(/\s+/g, " ").trim());
  return "";
}

function extractDescription(html) {
  const og = html.match(
    /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i
  );
  if (og) return decodeEntities(og[1].trim());
  const md = html.match(
    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i
  );
  if (md) return decodeEntities(md[1].trim());
  return "";
}

/**
 * @param {string} url  a URL already validated as http/https
 * @param {object} [opts] { fetchImpl, timeoutMs }
 * @returns {Promise<{title, description, site, unreadable}>}
 */
export async function readPageDetails(url, opts = {}) {
  const fetchImpl = opts.fetchImpl || fetch;
  const timeoutMs = opts.timeoutMs ?? 6000;
  const site = siteFromUrl(url);
  const fallback = {
    title: fallbackTitleFromUrl(url),
    description: "",
    site,
    unreadable: true,
  };

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetchImpl(url, {
      signal: controller.signal,
      redirect: "follow",
      headers: { "User-Agent": "BookmarksApp/1.0 (+personal)" },
    });
    if (!res.ok) return fallback;
    const ctype = res.headers.get("content-type") || "";
    if (!/text\/html|application\/xhtml/i.test(ctype)) return fallback;
    const html = await res.text();
    const title = extractTitle(html);
    const description = extractDescription(html);
    if (!title) return { ...fallback, description };
    return { title, description, site, unreadable: false };
  } catch {
    return fallback;
  } finally {
    clearTimeout(timer);
  }
}
