}

function beginEdit(id) {
  const bm = bookmarks.find((b) => b.id === id);
  if (!bm) return;
  drafts.set(id, {
    title: bm.title || "",
    url: bm.url || "",
    description: bm.description || "",
    note: bm.note || "",
    tags: [...(bm.tags || [])],
  });
  modes.set(id, "edit");
  render();
}

